import { Container, Graphics } from 'pixi.js';
import gsap from 'gsap';

import { IArc } from '../../types/cabinet';
import { killTweensIfAny } from '../../services/kill-tweens';

export class LoadingSpinner extends Container {
    private loadingGraphic: Graphics;
    private maskGraphic: Graphics;
    private arc: IArc;

    private lineThickness: number = 8;
    private opacity: number = 0.8;
    private loadDuration: number = 2;
    private holdDuration: number = 1;
    private loadingSegmentAngle: number = Math.PI * 0.25;

    private buttonRadius: number;

    public set holdAnimationDuration(duration: number) { this.holdDuration = duration; }

    constructor(buttonWidth: number, buttonHeight: number) {
        super();

        this.buttonRadius = Math.min(buttonWidth, buttonHeight) * 0.5;

        this.createLoadingGraphic();
        this.createMaskGraphic();

        this.position.set(0, -buttonHeight * 0.5);
    }

    private createLoadingGraphic(): void {
        this.loadingGraphic = new Graphics();

        const outerRadius = this.buttonRadius + (this.lineThickness * 0.5);
        this.loadingGraphic
            .circle(0, 0, outerRadius)
            .stroke({ width: this.lineThickness, color: 0xffffff, alpha: this.opacity });

        this.addChild(this.loadingGraphic);
    }

    private createMaskGraphic(): void {
        this.maskGraphic = new Graphics();
        this.maskGraphic.rotation = -(Math.PI * 0.5);

        this.addChild(this.maskGraphic);
    }

    private drawMask(startAngle: number, endAngle: number): void {
        this.maskGraphic.clear();

        const outerRadius = this.buttonRadius + (this.lineThickness * 0.5);

        this.maskGraphic
            .arc(0, 0, outerRadius, startAngle, endAngle)
            .stroke({ width: this.lineThickness + 2, color: 0xffffff, alpha: 1 });
    }

    private addMask(): void {
        this.loadingGraphic.mask = this.maskGraphic;
        this.addChild(this.maskGraphic);
    }

    private removeMask(): void {
        this.loadingGraphic.mask = null;
        this.removeChild(this.maskGraphic);
    }

    public animateLoading(): void {
        this.killTweens();
        this.addMask();

        this.arc = { startAngle: 0, endAngle: this.loadingSegmentAngle };

        gsap.to(this.arc, {
            duration: this.loadDuration,
            endAngle: Math.PI * 2 + this.loadingSegmentAngle,
            ease: 'Power0.easeNone',
            repeat: -1,
            onUpdate: () => { this.drawMask(this.arc.endAngle - this.loadingSegmentAngle, this.arc.endAngle); },
            onComplete: () => { this.removeMask(); }
        });
    }

    public animateHold(): void {
        this.killTweens();
        this.addMask();

        this.arc = { startAngle: 0, endAngle: 0 };

        gsap.to(this.arc, {
            duration: this.holdDuration,
            ease: 'Power0.easeNone',
            endAngle: Math.PI * 2,
            onUpdate: () => { this.drawMask(0, this.arc.endAngle); },
            onComplete: () => { this.removeMask(); }
        });
    }

    public killTweens(): void {
        killTweensIfAny([this.arc]);
        
        this.maskGraphic.clear();
        this.removeMask();
    }
}